<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {localFetch,readJson} from './http'
type Metrics={maintenance:number|null;buffer:number|null;loan:number|null;loan_cap:number|null;below130_amount:number|null;below130_share:number|null;below130_count:number|null;change20:number|null;index_buffer:number|null}
type Bin={label:string;amount:number|null;share:number|null;count:number|null;amount_range:number[];share_range:number[];count_range:number[]|null}
type Basket={key:string;label:string;etf:boolean;status:string;reasons:string[];metrics:Metrics;observed:{source_complete:boolean;financed_names:number|null;reported_financed_names:number;priced_names:number;finance_units:number|null;reported_finance_units:number;financed_market_value:number|null;market_cap:number|null;universe_names:number;cap_covered_names:number;cap_complete:boolean};distribution:{tier:string;D:number|null;low_difference:number|null;bins:Bin[]|null};events:{symbol:string;kind:string;date:string;cash:number|null}[];index_buffer_note:string|null}
type Subset={key:string;label:string;status:string;reasons:string[];count:number|null;members:{symbol:string;name:string;rank_value:number}[]|null;metrics:{maintenance:number|null;market_difference:number|null;below130_amount:number|null;change5_pp:number|null};membership_source:string;rs_date:string|null;change5_definition:string}
type Report={version:string;status:string;model_ready:boolean;dates:string[];as_of:string;source_as_of:string;created_at:string;vintage:string;frame:{date:string;baskets:Basket[];subsets:Record<string,Subset[]>;baseline20:string|null;baseline5:string|null;rs_saved_at:string|null;rs_anchors:Record<string,string>|null}}
const props=defineProps<{asOf?:string}>()
const data=ref<Report|null>(null),error=ref(''),loading=ref(false),day=ref(''),basket=ref('listed_stock'),market=ref('TWSE'),expanded=ref<Record<string,boolean>>({summary:true,distribution:true,subsets:true})
let request=0,disposed=false
const mainKeys=['listed_stock','otc_stock','etf_cap','etf_dividend','etf_leverage']
const main=computed(()=>data.value?.frame.baskets.filter(b=>mainKeys.includes(b.key))||[])
const other=computed(()=>data.value?.frame.baskets.filter(b=>!mainKeys.includes(b.key))||[])
const chosen=computed(()=>data.value?.frame.baskets.find(b=>b.key===basket.value))
const groups=computed(()=>data.value?.frame.subsets[market.value]||[])
const bands=['已破130%','距130%：0～7%','距130%：7～13%','距130%：13～22%','距130%：>22%']
const fmt=(v:number|null|undefined,d=2)=>v==null?'—':v.toLocaleString('zh-TW',{maximumFractionDigits:d})
const money=(v:number|null|undefined)=>v==null?'—':Math.abs(v)>=1e8?fmt(v/1e8)+' 億':Math.abs(v)>=1e4?fmt(v/1e4)+' 萬':fmt(v)+' 元'
const pct=(v:number|null|undefined)=>v==null?'—':fmt(v*100)+'%'
const rangeMoney=(b:Bin)=>b.amount!=null?money(b.amount):b.amount_range.map(v=>money(v)).join(' ～ ')
const rangePct=(b:Bin)=>b.share!=null?pct(b.share):b.share_range.map(v=>pct(v)).join(' ～ ')
function remember(){try{localStorage.setItem('margin-analytics.preferences.v1',JSON.stringify({basket:basket.value,market:market.value,expanded:expanded.value}))}catch{}}
function toggle(key:string,event:Event){expanded.value[key]=(event.target as HTMLDetailsElement).open;remember()}
async function load(){const id=++request;loading.value=true;error.value='';try{const r=await localFetch('/api/margin-statistics/analytics'+((props.asOf||day.value)?'?date='+encodeURIComponent(props.asOf||day.value):''));const v=await readJson<Report&{error?:string}>(r);if(!r.ok)throw Error(v.error||'讀取統計失敗');if(id===request&&!disposed)data.value=v}catch(e){if(id===request&&!disposed)error.value=e instanceof Error?e.message:String(e)}finally{if(id===request&&!disposed)loading.value=false}}
onMounted(()=>{try{const p=JSON.parse(localStorage.getItem('margin-analytics.preferences.v1')||'{}');if([...mainKeys,'etf_inverse','other'].includes(p.basket))basket.value=p.basket;if(['TWSE','TPEX'].includes(p.market))market.value=p.market;if(p.expanded&&typeof p.expanded==='object')for(const key of ['summary','distribution','subsets'])if(typeof p.expanded[key]==='boolean')expanded.value[key]=p.expanded[key]}catch{};load()})
watch(()=>props.asOf,()=>load())
onUnmounted(()=>{disposed=true;request++})
</script>
<template>
 <section class="analytics" aria-label="包3至5融資統計">
  <header><div><div class="eyebrow">FINANCING · BASKETS / DISTRIBUTION / COHORTS</div><h2>融資結構與風險分布</h2><p>五籃分開看，金額為主；先通過成本驗收，再判讀維持率。</p></div><span class="badge">包3～5 · 計算已接上，數值待驗收</span></header>
  <div v-if="error" class="notice error" role="alert">{{error}} <button @click="load">重新讀取</button></div>
  <p v-if="data?.status==='missing'" class="notice">統計封存尚未建立。開啟頁面不會啟動重算。</p>
  <template v-else-if="data?.frame">
   <div class="toolbar"><label v-if="!props.asOf">查看交易日<select v-model="day" aria-label="統計查看交易日" :disabled="loading" @change="load"><option value="">最新封存日 · {{data.source_as_of}}</option><option v-for="d in [...data.dates].reverse()" :key="d" :value="d">{{d}}</option></select></label><span class="date-tag" :data-analytics-date="data.as_of">{{data.as_of}} · {{fmt(data.dates.length,0)}}日封存</span><span class="loading" v-if="loading" role="status">讀取中…</span></div>
   <div class="notice"><b>成本模型尚未通過，維持率與風險金額暫不發布。</b><span>可核對的融資張數、市值與同日RS名單先列出；「—」表示尚不可計算，不表示風險為零。</span></div>
   <details :open="expanded.summary" @toggle="toggle('summary',$event)" class="package" aria-label="包3五籃摘要">
    <summary><span><i>03</i> 五籃摘要</span><small>上市／上櫃個股 · 三類ETF</small></summary>
    <div class="package-body">
     <div class="source-grid"><article v-for="b in main" :key="b.key"><div class="basket-name">{{b.label}}</div><small>融資部位市值<em>（不是借款金額）</em></small><strong>{{money(b.observed.financed_market_value)}}</strong><p>{{b.observed.finance_units==null?'融資來源不完整':fmt(b.observed.finance_units,0)+' 張／交易單位'}}</p><span v-if="!b.etf">{{b.observed.financed_names==null?'有融資家數未知':fmt(b.observed.financed_names,0)+' 檔有融資'}}</span><span v-else>ETF只比較金額，不列風險家數</span><span v-if="b.observed.reported_financed_names>b.observed.priced_names">融資部位缺收盤 {{b.observed.reported_financed_names-b.observed.priced_names}} 檔</span><span>籃子市值覆蓋 {{b.observed.cap_covered_names}} / {{b.observed.universe_names}} 檔</span></article></div>
     <div class="table-scroll" tabindex="0" aria-label="五籃維持率與金額，可左右捲動"><table><thead><tr><th>籃子</th><th>維持率</th><th>距130%跌幅</th><th>融資金額／占市值</th><th>&lt;130%金額／占比</th><th>&lt;130%家數</th><th>20日融資變化</th></tr></thead><tbody><tr v-for="b in main" :key="b.key" :data-basket-row="b.key"><td><b>{{b.label}}</b><small>待成本驗收</small></td><td>{{pct(b.metrics.maintenance)}}</td><td>{{pct(b.metrics.buffer)}}</td><td>{{money(b.metrics.loan)}}<small>{{pct(b.metrics.loan_cap)}}</small></td><td>{{money(b.metrics.below130_amount)}}<small>{{pct(b.metrics.below130_share)}}</small></td><td>{{b.etf?'不列':fmt(b.metrics.below130_count,0)}}</td><td>{{pct(b.metrics.change20)}}</td></tr></tbody></table></div>
     <p class="method">20日基準：{{data.frame.baseline20||'歷史不足'}}。市值分母包含同籃未融資成員；缺同日股數或行情時，不用局部市值充當全籃分母。分類依當日名稱與規則初分，尚未認證歷史商品屬性。</p>
     <details class="small-details"><summary>反向與未分類商品另列</summary><div v-for="b in other" :key="b.key" class="other-line"><b>{{b.label}}</b><span>已報告餘額 {{fmt(b.observed.reported_finance_units,0)}} 交易單位<em v-if="!b.observed.source_complete">（來源不完整的小計）</em></span><span>來源市值 {{money(b.observed.financed_market_value)}}</span></div><p>反向ETF不混入正向槓桿；債券、主題型與未確認商品不硬塞入三類ETF。</p></details>
    </div>
   </details>
   <details :open="expanded.distribution" @toggle="toggle('distribution',$event)" class="package" aria-label="包4五格風險分布">
    <summary><span><i>04</i> 五格風險分布</span><small>依距130%的緩衝分類</small></summary>
    <div class="package-body"><div class="distribution-toolbar"><select v-model="basket" aria-label="風險分布籃子" @change="remember"><option v-for="b in data.frame.baskets" :key="b.key" :value="b.key">{{b.label}}</option></select><span class="small-badge">{{chosen?.status==='blocked'?'待驗收 · 不畫比例':'兩方法比較'}}</span></div>
     <p class="method">緩衝＝1−130%÷維持率；低於130%時緩衝為負。金額按融資借款加總，非按股數或家數等權。</p>
     <div class="bands"><article v-for="(label,i) in bands" :key="label" :class="{blocked:!chosen?.distribution.bins}" :data-band="i"><div class="band-label">{{label}}</div><template v-if="chosen?.distribution.bins"><strong>{{rangeMoney(chosen.distribution.bins[i]!)}}</strong><span>{{rangePct(chosen.distribution.bins[i]!)}}</span><small v-if="!chosen.etf">{{chosen.distribution.bins[i]!.count==null?chosen.distribution.bins[i]!.count_range?.join('～'):chosen.distribution.bins[i]!.count}} 檔</small></template><template v-else><strong>—</strong><span>風險金額與比例待驗收</span><small v-if="!chosen?.etf">家數待驗收</small></template></article></div>
     <p v-if="chosen?.distribution.tier==='interval'" class="method">範圍僅表示平均法與FIFO的差異，不是統計信賴區間。</p>
     <details class="small-details"><summary>查看本籃尚未通過的條件</summary><ul><li v-for="reason in chosen?.reasons" :key="reason">{{reason}}</li></ul></details>
     <p class="method">除息會影響未還原市值。當日已保存的除權息標記：<template v-if="chosen?.events.length"><span v-for="e in chosen.events" :key="e.symbol+e.kind">{{e.symbol}} {{e.kind}}；</span></template><template v-else>0筆；不等於已確認沒有事件。</template> 尚無完整還原價診斷線。</p><p v-if="chosen?.index_buffer_note" class="method">{{chosen.index_buffer_note}}</p>
    </div>
   </details>
   <details :open="expanded.subsets" @toggle="toggle('subsets',$event)" class="package" aria-label="包5個股子集比較">
    <summary><span><i>05</i> 個股子集比較</span><small>四組名單 · ETF不列入</small></summary>
    <div class="package-body"><div class="market-buttons" role="group" aria-label="子集比較市場"><button :aria-pressed="market==='TWSE'" @click="market='TWSE';remember()">上市個股</button><button :aria-pressed="market==='TPEX'" @click="market='TPEX';remember()">上櫃個股</button></div>
     <p class="method">RS沿用本系統同日封存的跨市場排名順序，再與該市場有融資普通股取交集，各市場取前30；YTD基準沿用該份RS的加權指數。未保存同日資料時，保留空白。</p>
     <div class="subset-grid"><article v-for="s in groups" :key="s.key" :data-subset="s.key"><div class="subset-heading"><h3>{{s.label}}</h3><span>{{s.count==null?'名單待驗收':fmt(s.count,0)+' 檔'}}</span></div><p class="subset-source">{{s.membership_source}}<template v-if="s.rs_date"> · {{s.rs_date}}</template></p><div class="subset-readings"><div><small>維持率</small><b>{{pct(s.metrics.maintenance)}}</b></div><div><small>與同市場全部個股差距</small><b>{{s.metrics.market_difference==null?'—':fmt(s.metrics.market_difference*100)+' 個百分點'}}</b></div><div><small>&lt;130%融資金額</small><b>{{money(s.metrics.below130_amount)}}</b></div><div><small>固定成員5日維持率變化</small><b>{{s.metrics.change5_pp==null?'—':fmt(s.metrics.change5_pp)+' 個百分點'}}</b></div></div>
      <details class="small-details"><summary>{{s.members==null?'查看名單未開放原因':'查看來源名單（非買賣訊號）'}}</summary><div v-if="s.members?.length" class="member-scroll"><div v-for="(r,i) in s.members" :key="r.symbol" class="member"><span>{{i+1}}.</span><b>{{r.name}} <small>{{r.symbol}}</small></b><span>{{s.key==='rs30'?'RS '+fmt(r.rank_value):s.key==='ytd'?'超大盤 '+fmt(r.rank_value)+'%':money(r.rank_value)}}</span></div></div><p v-else-if="s.members?.length===0">同日來源可用，但沒有符合交集條件的成員。</p><ul><li v-for="r in s.reasons" :key="r">{{r}}</li></ul></details>
     </article></div>
     <p class="method">5日基準：{{data.frame.baseline5||'歷史不足'}}。採本日成員固定回看，維持率差以百分點表示；這是描述統計，不是當時可交易的回測結果。</p>
     <p class="method">RS原始保存時間：{{data.frame.rs_saved_at?.replace('T',' ')||'本日沒有RS封存'}}。{{data.vintage}}。</p>
    </div>
   </details>
   <footer>方法 {{data.version}} · 實際保存 {{data.created_at.slice(0,16).replace('T',' ')}} · 只讀封存，不更新策略或帳戶</footer>
  </template><p v-else-if="loading" class="loading" role="status">正在讀取包3～5封存…</p>
 </section>
</template>
<style scoped>
.analytics{min-width:0;background:#fff;border:1px solid #dce5d6;border-radius:14px;padding:24px;margin:20px 0;color:#385640}.analytics header{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.eyebrow{font-size:10px;letter-spacing:1.6px;color:#8a9a7e}h2{font-size:22px;margin:8px 0}header p{font-size:12px;color:#89997f;margin:8px 0}.badge,.small-badge{align-self:flex-start;background:#fbf0df;color:#a38141;border-radius:20px;padding:8px 12px;font-size:10px}.toolbar{display:flex;align-items:center;gap:15px;flex-wrap:wrap;margin:20px 0}.toolbar label{display:flex;flex-direction:column;gap:5px;font-size:10px;color:#8b9b7f}select,button{font:inherit;color:inherit;border:1px solid #dce5d6;border-radius:7px;background:#fff;padding:8px 10px;font-size:12px;max-width:100%}button{cursor:pointer}.date-tag{font-size:12px;font-weight:700}.notice{background:#faf7ee;padding:13px 16px;border-radius:8px;color:#a18443;font-size:12px;line-height:1.9;margin:17px 0}.notice b,.notice span{display:block}.error{color:#b56553}.package{border-top:1px solid #e4eadf;margin-top:20px}.package>summary{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px 0;cursor:pointer;list-style:none}.package>summary:after{content:'＋';color:#8c9b80}.package[open]>summary:after{content:'−'}.package>summary>span{display:flex;align-items:center;gap:10px;font-size:17px;font-weight:700}.package>summary small{font-size:10px;color:#8f9d83;margin-left:auto}.package i{font-style:normal;background:#edf3e8;padding:5px 7px;border-radius:6px;font-size:11px}.source-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-bottom:20px}.source-grid article{padding:15px 13px;background:#f7f9f3;border:1px solid #e6ebdf;border-radius:8px;min-width:0}.basket-name{font-weight:700;font-size:13px;margin-bottom:15px}.source-grid small{font-size:10px;color:#8b9b7e;display:block;line-height:1.8}.source-grid em{font-style:normal;display:block;font-size:9px}.source-grid strong{font-size:21px;display:block;margin:9px 0;overflow-wrap:anywhere}.source-grid p,.source-grid span{font-size:10px;color:#899a7c;line-height:1.9;display:block;margin:0}.table-scroll{overflow-x:auto;border:1px solid #e3e9dc;border-radius:8px;max-width:100%}table{border-collapse:collapse;min-width:940px;width:100%;font-size:12px}th{background:#f6f8f0;color:#8c9c80;font-size:10px;text-align:right;padding:14px;white-space:nowrap}td{border-top:1px solid #e8ecdf;padding:16px 14px;text-align:right;white-space:nowrap}td:first-child,th:first-child{text-align:left}td small{display:block;font-size:10px;color:#a29474;margin-top:6px}.method{font-size:11px;line-height:1.95;color:#8a9a7e;margin:14px 0}.small-details{font-size:11px;line-height:1.95;color:#8c9b81;margin:15px 0}.small-details>summary{cursor:pointer;color:#6e8966;font-weight:600}.small-details ul{padding-left:20px}.other-line{display:flex;gap:18px;flex-wrap:wrap;padding:10px 0;border-bottom:1px solid #e8ecdf}.other-line em{font-style:normal;color:#b18b46}.distribution-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.bands{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin:18px 0}.bands article{border:1px solid #e2e8da;border-top:3px solid #89a389;padding:16px 12px;border-radius:8px;min-width:0}.bands .blocked{background:repeating-linear-gradient(135deg,#fff,#fff 9px,#fafbf8 9px,#fafbf8 11px);border-top:3px solid #d8dfd1;color:#9aa58d}.band-label{font-size:11px;font-weight:700}.bands strong{display:block;font-size:24px;margin:17px 0}.bands span,.bands small{display:block;font-size:10px;line-height:1.9}.market-buttons{display:flex;gap:5px;background:#eef3e8;border-radius:8px;padding:4px;width:fit-content}.market-buttons button{background:transparent;border:0}.market-buttons button[aria-pressed=true]{background:#fff;box-shadow:0 2px 4px #34523412;font-weight:700}.subset-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.subset-grid>article{border:1px solid #e0e8d8;border-radius:9px;padding:18px;min-width:0}.subset-heading{display:flex;justify-content:space-between;gap:10px;align-items:start}.subset-heading h3{font-size:15px;margin:0}.subset-heading>span{font-size:10px;white-space:nowrap;color:#a18443}.subset-source{font-size:10px;line-height:1.9;color:#8a9b7e;min-height:30px;margin:12px 0}.subset-readings{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.subset-readings small{display:block;color:#8a9c7c;font-size:10px;line-height:1.8}.subset-readings b{display:block;font-size:20px;margin-top:6px}.member-scroll{max-height:260px;overflow:auto;margin-top:13px}.member{display:flex;gap:8px;align-items:baseline;padding:8px 0;border-bottom:1px solid #ecf0e5;font-size:11px}.member>b{font-weight:500;flex:1}.member small{font-size:9px;color:#9aa58d}.member>span:first-child{font-size:10px;color:#a1ac95}.member>span:last-child{white-space:nowrap;font-size:10px}footer{font-size:10px;color:#97a28b;border-top:1px solid #e5eadf;padding-top:17px;margin-top:20px;line-height:1.9}.loading{font-size:11px;color:#8e9d83}@media(max-width:1150px){.source-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.bands{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:650px){.analytics{padding:16px}.source-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.bands{grid-template-columns:repeat(2,minmax(0,1fr))}.subset-grid{grid-template-columns:1fr}.package>summary small{display:none}.package>summary>span{font-size:16px}.source-grid strong{font-size:20px}.toolbar{gap:10px}.subset-readings b{font-size:18px}.member{gap:5px}h2{font-size:21px}.badge{font-size:9px}}
</style>
